import React, { useState } from 'react';
import axios from 'axios';
import './ManufacturingDashboard.css';

const defaultParams = {
  Granulation_Time: '',
  Binder_Amount: '',
  Drying_Temp: '',
  Drying_Time: '',
  Compression_Force: '',
  Machine_Speed: '',
  Lubricant_Conc: '',
  Moisture_Content: '',
  Tablet_Weight: '',
};

const paramLabels = {
  Granulation_Time: { label: 'Granulation Time', unit: 'min', icon: '⏱' },
  Binder_Amount: { label: 'Binder Amount', unit: 'kg', icon: '🧪' },
  Drying_Temp: { label: 'Drying Temperature', unit: '°C', icon: '🌡' },
  Drying_Time: { label: 'Drying Time', unit: 'min', icon: '⏳' },
  Compression_Force: { label: 'Compression Force', unit: 'kN', icon: '💪' },
  Machine_Speed: { label: 'Machine Speed', unit: 'rpm', icon: '⚙️' },
  Lubricant_Conc: { label: 'Lubricant Concentration', unit: '%', icon: '💧' },
  Moisture_Content: { label: 'Moisture Content', unit: '%', icon: '🌊' },
  Tablet_Weight: { label: 'Tablet Weight', unit: 'mg', icon: '⚖️' },
};

const resultConfig = {
  Hardness: { label: 'Hardness', unit: 'N', icon: '💎', color: '#4f8ef7' },
  Friability: { label: 'Friability', unit: '%', icon: '🧱', color: '#f7774f' },
  Dissolution_Rate: { label: 'Dissolution Rate', unit: '%', icon: '⚗️', color: '#4ff7a0' },
  Content_Uniformity: { label: 'Content Uniformity', unit: '%', icon: '📊', color: '#f7d44f' },
};

function getQualityStatus(key, value) {
  if (key === 'Friability') {
    return value < 1 ? { label: 'PASS', ok: true } : { label: 'FAIL', ok: false };
  }
  if (key === 'Dissolution_Rate') {
    return value >= 75 ? { label: 'PASS', ok: true } : { label: 'FAIL', ok: false };
  }
  if (key === 'Content_Uniformity') {
    return value >= 95 ? { label: 'PASS', ok: true } : { label: 'FAIL', ok: false };
  }
  if (key === 'Hardness') {
    return value >= 4 && value <= 10 ? { label: 'PASS', ok: true } : { label: 'FAIL', ok: false };
  }
  return null;
}

export default function ManufacturingDashboard() {
  const [params, setParams] = useState(defaultParams);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    setParams({ ...params, [e.target.name]: e.target.value });
  };

  const handlePredict = async () => {
    setError('');
    setResults(null);
    // Validate all fields
    for (const key of Object.keys(params)) {
      if (params[key] === '') {
        setError(`Please fill in all fields. Missing: ${paramLabels[key].label}`);
        return;
      }
    }
    const payload = {};
    for (const key of Object.keys(params)) {
      payload[key] = parseFloat(params[key]);
    }
    setLoading(true);
    try {
      const response = await axios.post('http://localhost:8000/predict_batch', payload);
      setResults(response.data);
    } catch (err) {
      setError(
        err.response?.data?.detail ||
        err.message ||
        'Failed to connect to the prediction server.'
      );
    } finally {
      setLoading(false);
    }
  };

  const allPassed = results
    ? Object.keys(resultConfig).every((k) => {
        const s = getQualityStatus(k, results[k]);
        return s ? s.ok : true;
      })
    : null;

  return (
    <div className="mfg-dashboard">
      {/* Header */}
      <header className="mfg-header">
        <div className="mfg-header-inner">
          <div className="mfg-logo">
            <div className="mfg-logo-icon">
              <svg viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="20" cy="20" r="18" stroke="url(#logoGrad)" strokeWidth="2.5" />
                <path d="M12 20 L20 12 L28 20 L20 28 Z" fill="url(#logoGrad)" opacity="0.8" />
                <circle cx="20" cy="20" r="4" fill="#fff" />
                <defs>
                  <linearGradient id="logoGrad" x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse">
                    <stop stopColor="#4f8ef7" />
                    <stop offset="1" stopColor="#a855f7" />
                  </linearGradient>
                </defs>
              </svg>
            </div>
            <div>
              <span className="mfg-logo-title">VIGIL<span className="mfg-logo-ai">-AI</span></span>
              <span className="mfg-logo-sub">Manufacturing Intelligence Platform</span>
            </div>
          </div>
          <div className="mfg-header-badges">
            <span className="badge badge-live">● LIVE</span>
            <span className="badge badge-system">MFG-SYS v2.4</span>
          </div>
        </div>
      </header>

      <main className="mfg-main">
        {/* Left Panel: Form */}
        <section className="mfg-panel mfg-form-panel">
          <div className="panel-header">
            <span className="panel-icon">⚙️</span>
            <div>
              <h2 className="panel-title">Batch Parameters</h2>
              <p className="panel-subtitle">Configure manufacturing inputs for quality prediction</p>
            </div>
          </div>

          <div className="mfg-form-grid">
            {Object.keys(params).map((key) => {
              const meta = paramLabels[key];
              return (
                <div className="mfg-field" key={key}>
                  <label className="mfg-label">
                    <span className="field-icon">{meta.icon}</span>
                    {meta.label}
                    <span className="field-unit">{meta.unit}</span>
                  </label>
                  <input
                    className="mfg-input"
                    type="number"
                    name={key}
                    value={params[key]}
                    onChange={handleChange}
                    placeholder={`Enter ${meta.label.toLowerCase()}`}
                    step="any"
                  />
                </div>
              );
            })}
          </div>

          {error && (
            <div className="mfg-error">
              <span>⚠️</span> {error}
            </div>
          )}

          <button
            className={`mfg-predict-btn ${loading ? 'loading' : ''}`}
            onClick={handlePredict}
            disabled={loading}
          >
            {loading ? (
              <>
                <span className="btn-spinner"></span>
                Analyzing Batch...
              </>
            ) : (
              <>
                <span>🔮</span>
                Predict Batch Quality
              </>
            )}
          </button>
        </section>

        {/* Right Panel: Results */}
        <section className="mfg-panel mfg-results-panel">
          <div className="panel-header">
            <span className="panel-icon">📊</span>
            <div>
              <h2 className="panel-title">Quality Predictions</h2>
              <p className="panel-subtitle">AI-powered batch quality analysis output</p>
            </div>
          </div>

          {!results && !loading && (
            <div className="mfg-empty-state">
              <div className="empty-icon">🧬</div>
              <p className="empty-title">No Prediction Yet</p>
              <p className="empty-sub">Fill in parameters and click "Predict Batch Quality" to run the AI model.</p>
            </div>
          )}

          {loading && (
            <div className="mfg-loading-state">
              <div className="loading-ring"></div>
              <p>Running AI Model...</p>
              <p className="loading-sub">Analyzing manufacturing parameters</p>
            </div>
          )}

          {results && (
            <>
              <div className={`mfg-verdict ${allPassed ? 'verdict-pass' : 'verdict-fail'}`}>
                <span>{allPassed ? '✅' : '❌'}</span>
                <span>{allPassed ? 'Batch Approved — All Parameters Within Spec' : 'Batch Rejected — One or More Parameters Out of Spec'}</span>
              </div>
              <div className="mfg-result-grid">
                {Object.keys(resultConfig).map((key) => {
                  const cfg = resultConfig[key];
                  const value = results[key];
                  const status = getQualityStatus(key, value);
                  return (
                    <div
                      className="result-card"
                      key={key}
                      style={{ '--card-color': cfg.color }}
                    >
                      <div className="result-card-header">
                        <span className="result-icon">{cfg.icon}</span>
                        <span className="result-label">{cfg.label}</span>
                        {status && (
                          <span className={`result-badge ${status.ok ? 'badge-pass' : 'badge-fail'}`}>
                            {status.label}
                          </span>
                        )}
                      </div>
                      <div className="result-value">
                        {typeof value === 'number' ? value.toFixed(3) : value}
                        <span className="result-unit">{cfg.unit}</span>
                      </div>
                      <div className="result-bar-track">
                        <div
                          className="result-bar-fill"
                          style={{
                            width: `${Math.min(100, Math.abs(parseFloat(value || 0)))}%`,
                            background: cfg.color,
                          }}
                        ></div>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="mfg-timestamp">
                <span>⏱</span> Prediction generated at {new Date().toLocaleTimeString()} on {new Date().toLocaleDateString()}
              </div>
            </>
          )}
        </section>
      </main>

      <footer className="mfg-footer">
        <span>VIGIL-AI Manufacturing Intelligence © 2025</span>
        <span>Powered by FastAPI · React · Scikit-Learn</span>
      </footer>
    </div>
  );
}
